function seedDeliverableTaskCatalog(){if(db.prepare('SELECT 1 FROM app_migrations WHERE migration_key=?').get('deliverable-task-catalog-v1'))return;if(!db.prepare('SELECT 1 FROM task_types WHERE is_active=1 LIMIT 1').get())return;db.exec('BEGIN IMMEDIATE');try{for(const entry of deliverableTaskCatalogSource.deliverables){let deliverable=db.prepare('SELECT deliverable_id FROM deliverables WHERE deliverable_name=? COLLATE NOCASE').get(entry.deliverable);if(!deliverable){deliverable={deliverable_id:crypto.randomUUID()};db.prepare('INSERT INTO deliverables(deliverable_id,deliverable_name,is_active) VALUES (?,?,1)').run(deliverable.deliverable_id,entry.deliverable)}else db.prepare('UPDATE deliverables SET is_active=1 WHERE deliverable_id=?').run(deliverable.deliverable_id);for(const name of entry.task_types){const task=db.prepare('SELECT task_type_id FROM task_types WHERE task_type_name=? COLLATE NOCASE AND is_active=1').get(name);if(task)db.prepare('INSERT OR IGNORE INTO deliverable_task_types(deliverable_id,task_type_id) VALUES (?,?)').run(deliverable.deliverable_id,task.task_type_id)}}const names=deliverableTaskCatalogSource.deliverables.map(x=>x.deliverable);for(const row of db.prepare('SELECT deliverable_id,deliverable_name FROM deliverables WHERE is_active=1').all())if(!names.some(name=>name.toLowerCase()===row.deliverable_name.toLowerCase()))db.prepare('UPDATE deliverables SET is_active=0 WHERE deliverable_id=?').run(row.deliverable_id);db.prepare('INSERT INTO app_migrations(migration_key) VALUES (?)').run('deliverable-task-catalog-v1');db.exec('COMMIT')}catch(error){try{db.exec('ROLLBACK')}catch{}throw error}}
seedDeliverableTaskCatalog();

ensureColumn('project_task_plan','planned_quantity_override','INTEGER CHECK(planned_quantity_override IS NULL OR planned_quantity_override>=0)');
function migrateDifficultyLevelRange(){
 const names=['task_type_weights','task_type_capacities','deliverable_task_ratios','project_task_plan','tasks'];
 const rebuild=[];
 for(const name of names){const entry=db.prepare("SELECT sql FROM sqlite_master WHERE type='table' AND name=?").get(name);if(entry?.sql&&/difficulty_level\s+BETWEEN\s+1\s+AND\s+6/i.test(entry.sql))rebuild.push({name,sql:entry.sql,indexes:db.prepare("SELECT sql FROM sqlite_master WHERE type='index' AND tbl_name=? AND sql IS NOT NULL").all(name).map(x=>x.sql)})}
 if(!rebuild.length)return;
 fs.mkdirSync(backupDirectory,{recursive:true});const backupPath=path.join(backupDirectory,'ruang-proyek-'+new Date().toISOString().replace(/[:.]/g,'-')+'-pre-level8.sqlite');db.exec("VACUUM INTO '"+backupPath.replace(/'/g,"''")+"'");
 db.exec('PRAGMA foreign_keys=OFF; BEGIN IMMEDIATE');
 try{for(const item of rebuild){const temp=item.name+'_level8_migration';db.exec('DROP TABLE IF EXISTS "'+temp+'"');const matcher=new RegExp('^(CREATE TABLE\\s+(?:IF NOT EXISTS\\s+)?)(?:"?'+item.name+'"?)','i');const create=item.sql.replace(matcher,'$1"'+temp+'"').replace(/difficulty_level\s+BETWEEN\s+1\s+AND\s+6/ig,'difficulty_level BETWEEN 1 AND 8');db.exec(create);db.exec('INSERT INTO "'+temp+'" SELECT * FROM "'+item.name+'"');db.exec('DROP TABLE "'+item.name+'"');db.exec('ALTER TABLE "'+temp+'" RENAME TO "'+item.name+'"');for(const indexSql of item.indexes)db.exec(indexSql)}db.exec('COMMIT')}catch(error){try{db.exec('ROLLBACK')}catch{}throw error}finally{db.exec('PRAGMA foreign_keys=ON')}
}
migrateDifficultyLevelRange();
db.exec(`CREATE TABLE IF NOT EXISTS project_task_dependencies(project_id TEXT NOT NULL REFERENCES projects(project_id) ON DELETE CASCADE,task_type_id TEXT NOT NULL REFERENCES task_types(task_type_id) ON DELETE CASCADE,predecessor_task_type_id TEXT NOT NULL REFERENCES task_types(task_type_id) ON DELETE CASCADE,PRIMARY KEY(project_id,task_type_id,predecessor_task_type_id),CHECK(task_type_id<>predecessor_task_type_id)); CREATE TABLE IF NOT EXISTS project_department_staffing(project_id TEXT NOT NULL REFERENCES projects(project_id) ON DELETE CASCADE,department_id TEXT NOT NULL REFERENCES departments(department_id) ON DELETE CASCADE,personnel_count INTEGER NOT NULL CHECK(personnel_count>=0),captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,department_id)); CREATE TABLE IF NOT EXISTS default_task_type_dependencies(task_type_id TEXT NOT NULL REFERENCES task_types(task_type_id) ON DELETE CASCADE,predecessor_task_type_id TEXT NOT NULL REFERENCES task_types(task_type_id) ON DELETE CASCADE,PRIMARY KEY(task_type_id,predecessor_task_type_id),CHECK(task_type_id<>predecessor_task_type_id));`);
