function readBody(req,maxLength=1000000){return new Promise((resolve,reject)=>{let raw='';req.on('data',c=>{raw+=c;if(raw.length>maxLength){reject(Error('Request terlalu besar'));req.destroy()}});req.on('end',()=>{try{resolve(JSON.parse(raw||'{}'))}catch{reject(Error('Format request tidak valid'))}});req.on('error',reject)})}
